import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易纬坤灵图〔汉〕郑玄","description":"易纬坤灵图 - 易纬坤灵图〔汉〕郑玄","frontmatter":{"title":"易纬坤灵图〔汉〕郑玄","description":"易纬坤灵图 - 易纬坤灵图〔汉〕郑玄"},"headers":[],"relativePath":"zh/classics/yiwei-kunlingtu/001.md","filePath":"zh/classics/yiwei-kunlingtu/001.md"}'),r={name:"zh/classics/yiwei-kunlingtu/001.md"};function c(l,a,o,d,p,u){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易纬坤灵图〔汉〕郑玄",tabindex:"-1"},[n("易纬坤灵图〔汉〕郑玄 "),e("a",{class:"header-anchor",href:"#易纬坤灵图〔汉〕郑玄","aria-label":"Permalink to “易纬坤灵图〔汉〕郑玄”"},"​")],-1),e("p",null,"钦定四库全书易纬坤灵图 ​汉 郑康成 注邱序曰：天经曰：「乾，元亨利贞。」爻曰：「飞龙在天，利见大人。」 ​谓易为天经者，圣人所制作。乾有四德，「飞龙在天」，此圣人以至德居天子位也。序此之言说之也。故德配天地，天地不私公位，称之曰「帝」。 ​古者圣人德如此也，不私公位，不传之子孙，禅于能者，与天同，故以天称之也。故尧，天之精阳，万物莫不从者，故乾居西北，乾用事，万物蛰伏。致乎万物蛰伏，故能致乎万人之化。 ​「立天之道，曰阴与阳」，言尧乃天之阳精所生，所以能为明君，而能假人也。万物蛰伏，象施化功成，人人化，故然也。经曰「用九」， ​尧时贤圣为圣德化于天下故耳。天之所首之，故经以明之。经曰：震下乾上，旡妄，天精起。 ​起犹立。乾为天，震为长子，天生长子，圣人立为天子，天下之人各得所，天所获旡妄也。帝必有洪水之灾，天生圣人使杀之，故言「乃统天」也。 ​初九震在子，坎为水，又年与艮同体，艮为山，水而渐山，是大水为人害，天故生圣君。尧求命之，是亦尧辜也。与乾统天之功同。邱括义：因象助类。辞曰：天无云而雷，先王以茂对时育万物。 ​茂，勉也。对，遂。育，长也。天之将雨，先必兴云而后雷。今乾在上，下无坎而有震，是以雷行天下，无云而雷。洪水之时，人苦雨之多，故尧于是茂勉，遂其教令，以养万物。以是众庶艰食，得以糊口焉。经曰：乾下艮上，大畜。天灾将至，预畜而待之，人免于饥，故曰元亨。 ​按：乾元序制记内「贤子孙继世而立」云云，疑此处注文上下皆通，各载其性，故曰利贞。 ​载之时，言得值也。言待尧养万物，将岁不饥，长幼情性，人自各得如此也。至德之萌，五星若连珠，日月如合璧。天精起斗口有位，鸡鸣斗运行复始，莫敢当之。黄星笰于北斗，必以戊己日，其先无芒，行文元武动事，莫之敢距。 ​按绎史引坤灵图云：「伏羲立九部而民易理。」又云：「?阳者火，火恶水，故食不饮。桑者上之液，木生火，故?以三月草颊会精，合相食。」隋书引坤灵图云：「河龙以正月辰见，白龙与五黑龙斗，白龙陵，故泰人有命。」郑康成云：「陵当为除。」今皆无其文。盖此本非完书，且有错入乾元序制记萹内者。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
